use std::sync::Arc;
use std::thread;

/// Sum `data` by splitting it across `workers` threads.
pub fn parallel_sum(data: Vec<i64>, workers: usize) -> i64 {
    let shared = Arc::new(data);
    let chunk = (shared.len() + workers - 1) / workers;
    let mut handles = Vec::new();
    for w in 0..workers {
        // BUG: `shared` is MOVED into the first closure; the loop's later
        // iterations can't use it and this does not compile (E0382).
        let handle = thread::spawn(move || {
            let start = w * chunk;
            let end = (start + chunk).min(shared.len());
            shared[start..end].iter().sum::<i64>()
        });
        handles.push(handle);
    }
    handles.into_iter().map(|h| h.join().unwrap()).sum()
}

