use conc_case::parallel_sum;

#[test]
fn sums_exactly() {
    let data: Vec<i64> = (1..=1000).collect();
    assert_eq!(parallel_sum(data, 4), 500500);
}

#[test]
fn uneven_chunks_and_single_worker() {
    let data: Vec<i64> = (1..=7).collect();
    assert_eq!(parallel_sum(data.clone(), 3), 28);
    assert_eq!(parallel_sum(data, 1), 28);
}

#[test]
fn more_workers_than_items() {
    assert_eq!(parallel_sum(vec![5, 5], 8), 10);
}

