use std::sync::Arc;
use std::thread;

pub fn parallel_sum(data: Vec<i64>, workers: usize) -> i64 {
    let shared = Arc::new(data);
    let chunk = (shared.len() + workers - 1) / workers;
    let mut handles = Vec::new();
    for w in 0..workers {
        let shared = Arc::clone(&shared);
        let handle = thread::spawn(move || {
            let start = if w == 0 { 0 } else { w * chunk - 1 };
            let end = (w * chunk + chunk).min(shared.len());
            shared[start.min(shared.len())..end].iter().sum::<i64>()
        });
        handles.push(handle);
    }
    handles.into_iter().map(|h| h.join().unwrap()).sum()
}
